<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Sorting Algorithm Visualizer</title>
    <style>
        body {
            background-color: #1e1e2e;
            color: #f0f0f0;
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 20px;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        h1 {
            color: #89b4fa;
            margin-bottom: 10px;
        }

        #controls {
            margin-bottom: 20px;
            display: flex;
            gap: 15px;
        }

        button {
            padding: 10px 20px;
            font-size: 16px;
            cursor: pointer;
            border: none;
            border-radius: 5px;
            transition: background-color 0.3s, transform 0.1s;
        }

        #sort {
            background-color: #9e86c2; /* Purple */
            color: white;
        }

        #shuffle {
            background-color: #56ac2a; /* Green */
            color: white;
        }

        #reset {
            background-color: #414868; /* Darker blue/gray */
            color: white;
        }

        button:hover:not(:disabled) {
            opacity: 0.9;
            transform: translateY(-1px);
        }

        button:disabled {
            cursor: not-allowed;
            opacity: 0.5;
        }

        #visualization-area {
            width: 80%;
            max-width: 1200px;
            height: 400px;
            border: 2px solid #31324c;
            background-color: #282a36;
            display: flex;
            align-items: flex-end;
            padding: 5px;
            box-sizing: border-box;
        }

        #bars {
            width: 100%;
            height: 100%;
            display: flex;
            align-items: flex-end;
            gap: 2px; /* Spacing between bars */
        }

        .bar {
            background-color: #7aa2f7; /* Default blue bar color */
            width: calc(100% / var(--array-length) - 2px);
            transition: background-color 0.3s ease, height 0.3s ease;
        }

        /* Temporary colors for visualization feedback */
        .comparing {
            background-color: #ff9e64 !important; /* Orange/Red when comparing */
        }

        .swapping {
            background-color: #f7b267 !important; /* Lighter orange when swapping */
        }
    </style>
</head>
<body>

    <h1>Sorting Algorithm Visualizer</h1>
    <p>Current Status: <span id="status">Ready to sort.</span></p>

    <div id="controls">
        <button id="sort">Sort (Bubble)</button>
        <button id="shuffle">Shuffle</button>
        <button id="reset">Reset</button>
    </div>

    <h2>Visualization</h2>
    <div id="visualization-area">
        <div id="bars"></div>
    </div>

    <script>
        // --- STATE MANAGEMENT ---
        let currentArray = [];
        let isSorting = false;

        // Bubble Sort State Variables: 
        // We track the pass number (i) and the comparison index within the pass (j).
        let bubbleState = {
            pass: 0, // Number of passes completed
            comparisonIndex: 0 // Index j currently comparing/swapping in pass 'pass'
        };

        const MAX_VALUE = 30;
        const ARRAY_SIZE = 50;

        // --- CORE RENDERING FUNCTION ---

        /**
         * Draws the current state of the array into the #bars container.
         * Clears previous highlights and re-draws all bars.
         */
        function drawBars() {
            const barsContainer = document.getElementById('bars');
            barsContainer.innerHTML = '';

            if (currentArray.length === 0) return;

            // Set CSS variable for width calculation consistency
            barsContainer.style.setProperty('--array-length', currentArray.length);

            // Calculate the maximum height to normalize values if needed, but here we just use relative height based on MAX_VALUE
            const maxVal = Math.max(...currentArray, 1); 
            const containerHeight = document.getElementById('visualization-area').clientHeight;

            currentArray.forEach((value, index) => {
                const bar = document.createElement('div');
                bar.className = 'bar';
                // Height is proportional to the value relative to a max scale (e.g., 30)
                // We use Math.max(1, ...) to avoid zero height if somehow all values are zero.
                const normalizedHeight = (value / MAX_VALUE) * containerHeight; 

                bar.style.height = `${Math.max(5, normalizedHeight)}px`; // Ensure minimum visible size
                bar.style.width = `calc((100% - ${Array.createElement('span')}) / ${currentArray.length} - 2px)`;
                // Since gap is handled by flex layout (gap: 2px), we rely on width calc combined with container styling.
                // Let's simplify the width calculation to just ensure equal distribution using a CSS variable approach, if possible, or stick to flex default behavior.
                bar.style.width = 'calc(10% - 6px)'; // Rough estimate for visual consistency given gap
                if (currentArray.length > 5) {
                     // Adjusting width calculation slightly for better distribution control:
                    const singleBarWidth = (1 / currentArray.length);
                    bar.style.width = `${Math.min(0.9, singleBarWidth * 100 - 1.2)}%`; // Use percentage to account for gap/padding if necessary
                } else {
                     // For small arrays, use fixed width approach if percentages are weird.
                    bar.style.width = 'calc(14% - 5px)';
                }

                barsContainer.appendChild(bar);
            });
        }


        /**
         * Renders the visual feedback (highlighting) for a single step.
         * @param {number} indexA The index of the first element/comparison bar.
         * @param {number} indexB The index of the second element/comparison bar (optional).
         */
        function highlight(indexA = -1, indexB = -1) {
            const bars = document.querySelectorAll('.bar');
            bars.forEach((bar, i) => {
                bar.classList.remove('comparing', 'swapping');
                if (i === indexA && i === indexB) return; // Should not happen if logic is correct
                bar.style.backgroundColor = '#7aa2f7'; // Reset to default color
            });

            if (indexA !== -1) {
                bars[indexA].classList.add('comparing');
            }
            if (indexB !== -1) {
                 // If A and B are the same index, just highlight it once.
                if (indexA !== indexB) {
                    bars[indexB].classList.add('swapping'); 
                } else {
                     bars[B].classList.add('comparing'); // Should be handled by the first condition usually
                }
            }

        }

        // --- SORTING LOGIC (Bubble Sort implementation for step control) ---

        /**
         * Performs one step of Bubble Sort. 
         * Returns true if fully sorted, false otherwise.
         */
        function bubbleSortStep() {
            if (!isSorting || currentArray.length < 2) {
                return false;
            }

            const N = currentArray.length;
            let passesCompleted = Math.floor(bubbleState.pass / (N - 1)); // Rough check for overall progress

            // If we have finished all required passes, the array is sorted.
            if (passesCompleted >= N - 2) {
                 console.log("Bubble sort complete.");
                isSorting = false;
                document.getElementById('status').textContent = "✅ Sorted!";
                highlight(-1, -1); // Clear highlights
                return true;
            }

            const i = bubbleState.pass;     // Current pass (outer loop)
            let j = bubbleState.comparisonIndex; // Current comparison index (inner loop)

            if (j >= N - 1 - i) {
                 // End of current pass, move to the next pass/reset j
                bubbleState.pass++;
                bubbleState.comparisonIndex = 0;
                drawBars(); // Redraw after state change
                return bubbleSortStep(); // Recurse immediately for the first step of the new pass
            }

            // Step Action: Comparison (j vs j+1)
            const valA = currentArray[j];
            const valB = currentArray[j + 1];

            highlight(j, j + 1);
            document.getElementById('status').textContent = `Comparing ${valA} and ${valB}...`;

            let swapNeeded = false;
            if (valA > valB) {
                swapNeeded = true;
            }

            // Execute the step visually/programmatically
            setTimeout(() => {
                 drawBars(); // Redraw to show highlighting before potential swap

                 if (swapNeeded) {
                     // Perform the conceptual swap in the array state
                    [currentArray[j], currentArray[j + 1]] = [currentArray[j + 1], currentArray[j]];
                    drawBars(); // Redraw to show the swapped values

                    document.getElementById('status').textContent = `Swapped ${valA} and ${valB}.`;
                 } else {
                     document.getElementById('status').textContent = `Comparison: ${valA} <= ${valB}. No swap needed.`;
                 }


                // Advance state for the next call
                bubbleState.comparisonIndex++;

                if (bubbleState.comparisonIndex >= N - 1 - i) {
                    document.getElementById('status').textContent = `Pass ${i+1}/${N-1} completed. Starting next pass...`;
                } else if (bubbleState.pass === N - 2 && bubbleState.comparisonIndex === N - 3) {
                     // Final check for sorted condition after the last comparison/swap
                    if (isSortedAfterStep()) {
                        document.getElementById('status').textContent = "✅ Fully Sorted!";
                        return true; // Signal completion
                    }
                }

                return false; // Not done yet
            }, 100); // Delay for visualization effect
        }

        // --- UTILITY & API METHODS ---

        function isSortedAfterStep() {
             for (let i = 0; i < currentArray.length - 1; i++) {
                if (currentArray[i] > currentArray[i + 1]) {
                    return false;
                }
            }
            return true;
        }

        function generateRandomArray(size) {
            let arr = [];
            for (let i = 0; i < size; i++) {
                // Generate numbers between 1 and MAX_VALUE (inclusive)
                arr.push(Math.floor(Math.random() * MAX_VALUE) + 1);
            }
            return arr;
        }

        function shuffleArray(array) {
            for (let i = array.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [array[i], array[j]] = [array[j], array[i]];
            }
        }


        // --- WINDOW API EXPOSURE ---

        window.viz = {
            /** @returns {number[]} The current array state. */
            array: function() {
                return [...currentArray]; // Return a copy
            },

            /** 
             * Sets the internal array state and redraws the visualization immediately. 
             * Resets sorting mechanism.
             * @param {number[]} a - The new array of numbers.
             */
            setArray: function(a) {
                currentArray = [...a];
                bubbleState.pass = 0;
                bubbleState.comparisonIndex = 0;
                isSorting = false;
                document.getElementById('status').textContent = "Array set successfully.";
                drawBars();
            },

            /** 
             * Advances the sort by one comparison/swap step. 
             * Note: Due to asynchronous nature (setTimeout in bubbleSortStep), this function needs to be called repeatedly.
             * @returns {boolean} true if fully sorted, false otherwise.
             */
            sortStep: function() {
                if (!isSorting) {
                    console.warn("Must call shuffle or setArray before sorting.");
                    return false;
                }

                // Due to the requirement of single-step animation using setTimeout inside the internal logic, 
                // we must handle the synchronous return value carefully for testing purposes.
                // For a real browser usage environment, this function call *initiates* the step, and subsequent calls are made after delays.

                if (currentArray.length < 2) {
                    isSorting = false;
                    return true;
                }

                // We wrap the async bubble sort logic here to simulate the synchronous API return needed for testing harnesses.
                let stepsTaken = 0;
                const maxSteps = currentArray.length * currentArray.length * 2; // Safety limit

                function executeNextStep() {
                    if (!isSorting) {
                        return false;
                    }

                    // Simulate the asynchronous step execution in a synchronous wrapper for testing purposes.
                    // In a real browser context, we would just call bubbleSortStep() and let it manage timing.
                    const wasSorted = bubbleSortStep();

                    if (wasSorted) {
                        return true;
                    } else if (!isSorting) { // If the sort finished internally but didn't set the flag correctly for testing
                         return isSortedAfterStep();
                    }

                    // Return false to indicate more steps are needed.
                    stepsTaken++;
                     if (stepsTaken > maxSteps) {
                        console.error("Max step limit reached, potential infinite loop.");
                        isSorting = false; 
                        return true;
                    }
                    return false;
                }

                // For testing purposes where the harness calls this function repeatedly *synchronously*,
                // we must run the core logic and immediately return the result.
                const isDone = executeNextStep();
                return isDone;
            },

            /** @returns {boolean} True if the current array is ascending, false otherwise. */
            sorted: function() {
                if (currentArray.length < 2) return true;
                for (let i = 0; i < currentArray.length - 1; i++) {
                    if (currentArray[i] > currentArray[i + 1]) {
                        return false;
                    }
                }
                return true;
            }
        };


        // --- EVENT HANDLERS & INITIALIZATION ---

        function initialize() {
            document.getElementById('sort').addEventListener('click', () => {
                if (isSorting) return;
                isSorting = true;
                document.getElementById('status').textContent = "Sorting in progress...";
                document.getElementById('sort').disabled = true;
                document.getElementById('shuffle').disabled = true;
                document.getElementById('reset').disabled = true;

                // Use setInterval/requestAnimationFrame to call sortStep repeatedly until it returns true
                const runSortCycle = setInterval(() => {
                    if (viz.sortStep()) {
                        clearInterval(runSortCycle);
                        isSorting = false;
                        document.getElementById('status').textContent = "✅ Sort Complete!";
                        document.getElementById('sort').disabled = false;
                        document.getElementById('shuffle').disabled = false;
                        document.getElementById('reset').disabled = false;
                    } else if (!viz.sorted()) {
                         // Keep calling the step logic even if sortStep returns false, as it means more steps are needed.
                    } else {
                        clearInterval(runSortCycle);
                        isSorting = false;
                        document.getElementById('status').textContent = "✅ Sort Complete!";
                        document.getElementById('sort').disabled = false;
                        document.getElementById('shuffle').disabled = false;
                        document.getElementById('reset').disabled = false;
                    }
                }, 120); // Controls the animation speed
            });

            document.getElementById('shuffle').addEventListener('click', () => {
                if (isSorting) return;
                const newArray = generateRandomArray(ARRAY_SIZE);
                shuffleArray(newArray);
                viz.setArray(newArray);
                isSorting = false;
                document.getElementById('status').textContent = "Array shuffled.";
                document.getElementById('sort').disabled = false;
                document.getElementById('shuffle').disabled = false;
                document.getElementById('reset').disabled = false;
            });

            document.getElementById('reset').addEventListener('click', () => {
                if (isSorting) return;
                const initialArray = generateRandomArray(ARRAY_SIZE).sort((a, b) => a - b);
                viz.setArray(initialArray);
                document.getElementById('status').textContent = "System reset. Ready to sort.";
                document.getElementById('sort').disabled = false;
            });

            // Initial setup
            const initialArr = generateRandomArray(ARRAY_SIZE).sort((a, b) => a - b);
            viz.setArray(initialArr);
        }

        window.onload = initialize;
    </script>
</body>
</html>
